</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Solution
{
    public static void main(String[] args) throws IOException
    {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null)
        {
            sb.append(line).append(' ');
        }

        StringTokenizer st = new StringTokenizer(sb.toString());
        int[] nums = new int[st.countTokens()];
        for (int i = 0; st.hasMoreTokens(); i++)
        {
            nums[i] = Integer.parseInt(st.nextToken());
        }

        int n = nums[0];
        int b = nums[1];
        int[] a = Arrays.copyOfRange(nums, 2, 2 + n);

        int[] odd = new int[n + 1];
        int[] even = new int[n + 1];

        for (int i = 1; i <= n; i++)
        {
            if ((a[i - 1] & 1) == 1)
            {
                odd[i] = odd[i - 1] + 1;
                even[i] = even[i - 1];
            }
            else
            {
                odd[i] = odd[i - 1];
                even[i] = even[i - 1] + 1;
            }
        }

        List<Integer> costs = new ArrayList<Integer>();
        int prev = 0;

        for (int i = 1; i < n; i++)
        {
            int oc = odd[i] - odd[prev];
            int ec = even[i] - even[prev];
            if (oc == ec)
            {
                costs.add(Math.abs(a[i] - a[i - 1]));
                prev = i;
            }
        }

        Collections.sort(costs);
        int sum = 0;
        int answer = 0;

        for (int c : costs)
        {
            if (sum + c > b) break;
            sum += c;
            answer++;
        }

        System.out.println(answer);
    }
}
